        return ()

    def start(self, partial, memory):
        best = None
        best_key = None
        for i in range(partial.S):
            if partial.h(i) == 0:
                continue
            ub_i = partial.ub(i)
            if ub_i <= 0:
                continue
            key = (-ub_i, -partial.bad(), partial.h(i), i)
            if best_key is None or key < best_key:
                best_key = key
                best = i
        if best is None:
            return ()
        return (best,)

    def done(self, partial, memory):
