            + dest_unsorted_after * self._auto_reduce_stack_score_w_dest_unsorted
            + dest_nonempty * self._auto_reduce_stack_score_w_dest_nonempty
        )

    def update(self, partial, memory, action):
        if not memory:
            return memory
        source = memory[0]
        if action.so != source:
            return memory
        return memory


def build_component(problem, **params):
    rules = [
        ReduceStackMacro(**params),
        SafePlacementRule(**params),
    ]
    return RuleMachine(problem, rules)

